// Same split the live ManyChat flow uses: one model reply becomes
// the two or three short DMs a human would actually fire off.
const raw = $input.first().json.output || "";

const messages = raw
  .replace(/\u2014/g, " ")
  .replace(/\u2019/g, "'")
  .replace(/"/g, "")
  .replace(/ && /g, "&&")
  .split(/&&/g)
  .map(m => m.trim().replace(/\.$/, ""))
  .filter(m => m !== "");

return { messages };
